import { useCallback, useEffect, useMemo, useState } from "react";
import {
  Bell, Bookmark, CalendarDays, Clapperboard, Compass, ContactRound, Flame, Heart,
  Home, Image as ImageIcon, LockKeyhole, LogOut, MessageCircle, MessageSquare,
  MoreHorizontal, Newspaper, Pencil, Plus, Search, Settings, Share2, ShieldCheck,
  Trash2, UserPlus, UsersRound, Video, X,
} from "lucide-react";
import type { Session } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";
import { FlammeSocialMessages } from "./FlammeSocialMessages";

const db = supabase as any;

type View = "accueil" | "publications" | "videos" | "groupes" | "messages" | "decouvrir" | "alertes" | "contacts" | "enregistres" | "evenements" | "recherche" | "compte" | "parametres";
type Profile = {
  id: string; handle: string; display_name: string; bio: string; avatar_path?: string | null; cover_path?: string | null;
  city?: string | null; website?: string | null; is_private: boolean; allow_messages: "everyone" | "contacts" | "nobody"; created_at: string;
};
type Post = { id: string; author_id: string; group_id?: string | null; content: string; kind: "post" | "video"; visibility: "public" | "contacts" | "only_me"; created_at: string; updated_at: string; };
type Media = { id: string; post_id: string; path: string; media_type: "image" | "video"; position: number };
type Comment = { id: string; post_id: string; author_id: string; content: string; created_at: string; parent_id?: string | null };
type Reaction = { id: string; post_id: string; user_id: string };
type Group = { id: string; owner_id: string; name: string; description: string; image_path?: string | null; visibility: "public" | "private" | "invite"; created_at: string };
type Follow = { id: string; follower_id: string; following_id: string; status: "pending" | "accepted" };
type EventRow = { id: string; creator_id: string; title: string; description: string; starts_at: string; place?: string | null; visibility: "public" | "private"; created_at: string };

type FeedData = {
  posts: Post[]; profiles: Map<string, Profile>; media: Media[]; reactions: Reaction[]; comments: Comment[]; saved: Set<string>;
};

const mainNav: Array<{ id: View; label: string; icon: typeof Home }> = [
  { id: "accueil", label: "Accueil", icon: Home },
  { id: "publications", label: "Publications", icon: Newspaper },
  { id: "videos", label: "Vidéos", icon: Clapperboard },
  { id: "groupes", label: "Groupes", icon: UsersRound },
  { id: "messages", label: "Messages", icon: MessageCircle },
];
const extraNav: Array<{ id: View; label: string; icon: typeof Home }> = [
  { id: "decouvrir", label: "Découvrir", icon: Compass },
  { id: "alertes", label: "Alertes", icon: Bell },
  { id: "contacts", label: "Contacts", icon: ContactRound },
  { id: "enregistres", label: "Enregistrés", icon: Bookmark },
  { id: "evenements", label: "Événements", icon: CalendarDays },
  { id: "parametres", label: "Paramètres", icon: Settings },
];

function cx(...values: Array<string | false | null | undefined>) { return values.filter(Boolean).join(" "); }
function avatarUrl(path?: string | null) { return path ? supabase.storage.from("flamme-avatars").getPublicUrl(path).data.publicUrl : null; }
function mediaUrl(path: string) { return supabase.storage.from("flamme-media").getPublicUrl(path).data.publicUrl; }
function dateLabel(value: string) { return new Date(value).toLocaleString("fr-FR", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }); }
function safeExt(file: File) { const name = file.name.toLowerCase(); const ext = name.includes(".") ? name.split(".").pop() : "bin"; return (ext || "bin").replace(/[^a-z0-9]/g, "").slice(0, 6) || "bin"; }

function FlameMark({ className = "h-8 w-8" }: { className?: string }) {
  return <span className={cx("inline-flex items-center justify-center rounded-[30%] bg-[#CE654B] text-white shadow-sm", className)}><Flame className="h-[62%] w-[62%] fill-current" /></span>;
}
function Avatar({ profile, size = "md" }: { profile?: Profile | null; size?: "sm" | "md" | "lg" }) {
  const src = avatarUrl(profile?.avatar_path); const sizes = size === "sm" ? "h-8 w-8 text-xs" : size === "lg" ? "h-20 w-20 text-2xl" : "h-10 w-10 text-sm";
  return src ? <img src={src} alt="" className={cx(sizes, "shrink-0 rounded-full object-cover ring-1 ring-black/5")} /> : <span className={cx(sizes, "flex shrink-0 items-center justify-center rounded-full bg-[#CE654B]/15 font-extrabold text-[#A84D38]")}>{profile?.display_name?.slice(0, 1)?.toUpperCase() || "F"}</span>;
}
function Panel({ children, className }: { children: React.ReactNode; className?: string }) { return <section className={cx("rounded-[1.5rem] border border-[#E6DED2] bg-[#FFFDF9] shadow-sm", className)}>{children}</section>; }
function Empty({ icon: Icon, title, text }: { icon: typeof Home; title: string; text: string }) { return <Panel className="p-8 text-center"><Icon className="mx-auto h-9 w-9 text-[#CE654B]/45" /><strong className="mt-3 block text-slate-900">{title}</strong><p className="mx-auto mt-1 max-w-md text-sm text-slate-500">{text}</p></Panel>; }

async function moderatePublicText(content: string, kind: string) {
  if (!content.trim()) return true;
  try {
    const response = await fetch("/api/flamme-social-moderate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ content, kind, scope: "public" }) });
    const result = await response.json() as { available?: boolean; decision?: string; reason?: string };
    if (result.available && result.decision === "review") return window.confirm(`Le filtre de modération recommande une vérification${result.reason ? ` : ${result.reason}` : ""}. Publier quand même ?`);
  } catch { /* Mistral is optional and never a security dependency. */ }
  return true;
}

async function notify(userId: string, actorId: string, kind: string, entityType: string, entityId: string) {
  if (!userId || userId === actorId) return;
  await db.from("flamme_notifications").insert({ user_id: userId, actor_id: actorId, kind, entity_type: entityType, entity_id: entityId }).then(() => undefined, () => undefined);
}

export function FlammeSocialApp() {
  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);

  const loadProfile = useCallback(async (nextSession: Session | null) => {
    setSession(nextSession);
    if (!nextSession?.user?.id) { setProfile(null); setLoading(false); return; }
    const { data } = await db.from("flamme_profiles").select("*").eq("id", nextSession.user.id).maybeSingle();
    setProfile(data ?? null); setLoading(false);
  }, []);

  useEffect(() => {
    let active = true;
    void supabase.auth.getSession().then(({ data }) => { if (active) void loadProfile(data.session); });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, nextSession) => { if (active) void loadProfile(nextSession); });
    return () => { active = false; listener.subscription.unsubscribe(); };
  }, [loadProfile]);

  if (loading) return <div className="flex min-h-screen items-center justify-center bg-[#F6F1E8] text-sm text-slate-500">Ouverture de Flamme…</div>;
  if (!session) return <AuthScreen />;
  if (!profile) return <ProfileSetup session={session} onCreated={(created) => setProfile(created)} />;
  return <SocialShell profile={profile} onProfileChange={setProfile} />;
}

function AuthScreen() {
  const [mode, setMode] = useState<"login" | "signup">("login");
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [busy, setBusy] = useState(false); const [message, setMessage] = useState<string | null>(null);
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setBusy(true); setMessage(null);
    try {
      if (mode === "login") {
        const { error } = await supabase.auth.signInWithPassword({ email: email.trim(), password }); if (error) throw error;
      } else {
        const { data, error } = await supabase.auth.signUp({ email: email.trim(), password }); if (error) throw error;
        if (!data.session) setMessage("Compte créé. Vérifie ton adresse e-mail avant de te connecter.");
      }
    } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Connexion impossible."); } finally { setBusy(false); }
  };
  return <main className="min-h-screen bg-[#F6F1E8] px-4 py-10 text-[#181716]"><div className="mx-auto grid min-h-[78vh] max-w-5xl items-center gap-8 lg:grid-cols-[1.05fr_.95fr]">
    <div className="px-2"><div className="flex items-center gap-3"><FlameMark className="h-12 w-12" /><div><h1 className="font-display text-4xl font-extrabold tracking-tight">Flamme</h1><span className="rounded-full bg-[#172638] px-2 py-0.5 text-[10px] font-bold tracking-widest text-white">BÊTA SOCIALE</span></div></div><h2 className="mt-7 max-w-xl font-display text-4xl font-extrabold leading-[1.02] sm:text-5xl">Publier. Échanger. Se retrouver.</h2><p className="mt-4 max-w-xl text-base leading-relaxed text-slate-600">Un espace social français intégré à Flamme : publications, vidéos, groupes, événements et messages chiffrés de bout en bout.</p><div className="mt-6 flex flex-wrap gap-2 text-xs font-semibold text-slate-600"><span className="rounded-full bg-white px-3 py-2">Interface en français</span><span className="rounded-full bg-white px-3 py-2">Supabase + RLS</span><span className="rounded-full bg-white px-3 py-2">Messages E2E</span></div><a href="/flamme" className="mt-7 inline-block text-sm font-semibold text-[#A84D38] underline-offset-4 hover:underline">← Retour à la recherche Flamme</a></div>
    <Panel className="p-5 sm:p-7"><div className="flex rounded-xl bg-[#F6F1E8] p-1"><button type="button" onClick={() => setMode("login")} className={cx("flex-1 rounded-lg px-3 py-2 text-sm font-bold", mode === "login" && "bg-white shadow-sm")}>Se connecter</button><button type="button" onClick={() => setMode("signup")} className={cx("flex-1 rounded-lg px-3 py-2 text-sm font-bold", mode === "signup" && "bg-white shadow-sm")}>Rejoindre Flamme</button></div><form onSubmit={submit} className="mt-5 space-y-3"><label className="block text-sm font-semibold">Adresse e-mail<input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} className="mt-1.5 w-full rounded-xl border border-[#E6DED2] bg-white px-3.5 py-3 font-normal outline-none focus:border-[#CE654B]" /></label><label className="block text-sm font-semibold">Mot de passe<input type="password" required minLength={8} value={password} onChange={(e) => setPassword(e.target.value)} className="mt-1.5 w-full rounded-xl border border-[#E6DED2] bg-white px-3.5 py-3 font-normal outline-none focus:border-[#CE654B]" /></label>{message && <p className="rounded-xl bg-amber-50 px-3 py-2 text-sm text-amber-900">{message}</p>}<button disabled={busy} className="w-full rounded-xl bg-[#172638] px-4 py-3 font-bold text-white disabled:opacity-50">{busy ? "Chargement…" : mode === "login" ? "Se connecter" : "Créer mon compte"}</button></form><p className="mt-4 text-xs leading-relaxed text-slate-500">Le compte Flamme utilise l’authentification du site mais ne donne aucun droit d’administration à Angel OS.</p></Panel>
  </div></main>;
}

function ProfileSetup({ session, onCreated }: { session: Session; onCreated: (profile: Profile) => void }) {
  const [displayName, setDisplayName] = useState(""); const [handle, setHandle] = useState(""); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(null); const normalized = handle.trim().toLowerCase().replace(/[^a-z0-9_]/g, ""); try { const { data, error: insertError } = await db.from("flamme_profiles").insert({ id: session.user.id, display_name: displayName.trim(), handle: normalized }).select("*").single(); if (insertError) throw insertError; onCreated(data as Profile); } catch (cause) { setError(cause instanceof Error ? cause.message : "Création du profil impossible."); } finally { setBusy(false); } };
  return <main className="flex min-h-screen items-center justify-center bg-[#F6F1E8] p-4"><Panel className="w-full max-w-lg p-6 sm:p-8"><div className="flex items-center gap-3"><FlameMark className="h-10 w-10" /><div><h1 className="text-xl font-extrabold">Créer ton profil Flamme</h1><p className="text-sm text-slate-500">Dernière étape avant le fil.</p></div></div><form className="mt-6 space-y-4" onSubmit={submit}><label className="block text-sm font-semibold">Nom affiché<input required maxLength={80} value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="mt-1.5 w-full rounded-xl border border-[#E6DED2] px-3.5 py-3 font-normal outline-none focus:border-[#CE654B]" placeholder="Ton nom ou pseudo" /></label><label className="block text-sm font-semibold">Identifiant<input required minLength={3} maxLength={24} value={handle} onChange={(e) => setHandle(e.target.value)} className="mt-1.5 w-full rounded-xl border border-[#E6DED2] px-3.5 py-3 font-normal outline-none focus:border-[#CE654B]" placeholder="exemple_24" /><span className="mt-1 block text-xs font-normal text-slate-500">3 à 24 caractères : lettres minuscules, chiffres et _</span></label>{error && <p className="rounded-xl bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}<button disabled={busy} className="w-full rounded-xl bg-[#CE654B] px-4 py-3 font-bold text-white disabled:opacity-50">{busy ? "Création…" : "Entrer dans Flamme"}</button></form></Panel></main>;
}

function SocialShell({ profile, onProfileChange }: { profile: Profile; onProfileChange: (profile: Profile) => void }) {
  const [view, setView] = useState<View>("accueil"); const [unread, setUnread] = useState(0);
  const refreshUnread = useCallback(async () => { const { count } = await db.from("flamme_notifications").select("id", { head: true, count: "exact" }).eq("user_id", profile.id).is("read_at", null); setUnread(count ?? 0); }, [profile.id]);
  useEffect(() => { void refreshUnread(); const timer = window.setInterval(() => void refreshUnread(), 30000); return () => window.clearInterval(timer); }, [refreshUnread]);
  const content = (() => {
    switch (view) {
      case "accueil": return <FeedView me={profile} showComposer />;
      case "publications": return <FeedView me={profile} showComposer />;
      case "videos": return <FeedView me={profile} kind="video" showComposer />;
      case "groupes": return <GroupsView me={profile} />;
      case "messages": return <FlammeSocialMessages me={profile} />;
      case "decouvrir": return <PeopleView me={profile} mode="discover" />;
      case "contacts": return <PeopleView me={profile} mode="contacts" />;
      case "alertes": return <AlertsView me={profile} onRead={refreshUnread} />;
      case "enregistres": return <FeedView me={profile} savedOnly showComposer={false} />;
      case "evenements": return <EventsView me={profile} />;
      case "recherche": return <SearchView me={profile} />;
      case "compte": return <AccountView me={profile} onChange={onProfileChange} />;
      case "parametres": return <SettingsView me={profile} onChange={onProfileChange} />;
    }
  })();
  return <div className="min-h-screen bg-[#F6F1E8] text-[#181716]">
    <header className="sticky top-0 z-40 border-b border-[#E6DED2] bg-[#FFFDF9]/95 backdrop-blur"><div className="mx-auto flex h-16 max-w-[1500px] items-center gap-3 px-3 sm:px-5"><button onClick={() => setView("accueil")} className="flex items-center gap-2"><FlameMark className="h-9 w-9" /><span className="hidden font-display text-xl font-extrabold sm:inline">Flamme</span><span className="rounded-full bg-[#172638] px-2 py-0.5 text-[9px] font-bold tracking-wider text-white">BÊTA</span></button><div className="ml-auto flex items-center gap-1.5"><button onClick={() => setView("recherche")} aria-label="Recherche" className="flex h-10 w-10 items-center justify-center rounded-full hover:bg-[#F6F1E8]"><Search className="h-5 w-5" /></button><button onClick={() => setView("alertes")} aria-label="Alertes" className="relative flex h-10 w-10 items-center justify-center rounded-full hover:bg-[#F6F1E8]"><Bell className="h-5 w-5" />{unread > 0 && <span className="absolute right-1 top-1 min-w-4 rounded-full bg-[#CE654B] px-1 text-center text-[9px] font-bold leading-4 text-white">{Math.min(99, unread)}</span>}</button><button onClick={() => setView("compte")} className="ml-1 rounded-full" aria-label="Mon compte"><Avatar profile={profile} /></button></div></div></header>
    <div className="mx-auto grid max-w-[1500px] gap-5 px-3 py-4 pb-24 sm:px-5 lg:grid-cols-[230px_minmax(0,760px)_260px] lg:pb-8 xl:grid-cols-[250px_minmax(0,820px)_280px]">
      <aside className="sticky top-20 hidden h-fit lg:block"><nav className="space-y-1">{[...mainNav, ...extraNav].map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setView(id)} className={cx("flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold transition", view === id ? "bg-[#FFFDF9] text-[#A84D38] shadow-sm" : "text-slate-700 hover:bg-white/60")}><Icon className="h-5 w-5" />{label}{id === "alertes" && unread > 0 && <span className="ml-auto rounded-full bg-[#CE654B] px-2 py-0.5 text-[10px] text-white">{unread}</span>}</button>)}<button onClick={() => setView("compte")} className={cx("flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold", view === "compte" ? "bg-[#FFFDF9] text-[#A84D38] shadow-sm" : "hover:bg-white/60")}><Avatar profile={profile} size="sm" />Mon compte</button></nav><a href="/flamme" className="mt-5 block px-3 text-xs font-semibold text-slate-500 hover:text-[#A84D38]">← Recherche Flamme</a></aside>
      <main className="min-w-0">{content}</main>
      <aside className="sticky top-20 hidden h-fit space-y-3 lg:block"><Panel className="p-4"><div className="flex items-center gap-2 font-bold text-[#172638]"><ShieldCheck className="h-5 w-5 text-[#CE654B]" /> Sécurité Flamme</div><p className="mt-2 text-xs leading-relaxed text-slate-600">Les messages privés utilisent Web Crypto. Mistral peut aider à modérer les contenus publics, jamais à déchiffrer les conversations.</p></Panel><Panel className="p-4"><strong className="text-sm">Version bêta</strong><p className="mt-1 text-xs leading-relaxed text-slate-500">Certaines fonctions et règles de confidentialité peuvent évoluer. Les médias privés restent volontairement limités tant que leur stockage n’est pas chiffré de bout en bout.</p></Panel></aside>
    </div>
    <nav className="fixed inset-x-0 bottom-0 z-50 border-t border-[#E6DED2] bg-[#FFFDF9]/97 pb-[env(safe-area-inset-bottom)] shadow-[0_-10px_30px_rgba(0,0,0,.04)] lg:hidden"><div className="grid grid-cols-5">{mainNav.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setView(id)} className={cx("flex min-h-16 flex-col items-center justify-center gap-1 text-[10px] font-semibold", view === id ? "text-[#CE654B]" : "text-slate-500")}><Icon className="h-5 w-5" />{label === "Publications" ? "Publier" : label}</button>)}</div></nav>
  </div>;
}

function Composer({ me, groupId, forceVideo, onCreated }: { me: Profile; groupId?: string; forceVideo?: boolean; onCreated: () => void }) {
  const [content, setContent] = useState(""); const [visibility, setVisibility] = useState<"public" | "contacts" | "only_me">("public"); const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); const text = content.trim(); if (!text && !file) return; setBusy(true); setError(null); try {
    if (file && visibility !== "public") throw new Error("En bêta, les médias sont acceptés uniquement dans les publications publiques. Les contenus privés restent texte uniquement pour ne pas promettre une confidentialité inexistante.");
    if (file && !file.type.match(/^(image\/(jpeg|png|webp)|video\/(mp4|webm))$/)) throw new Error("Format non pris en charge.");
    if (file && file.size > 50 * 1024 * 1024) throw new Error("Le fichier dépasse 50 Mo.");
    if (file?.type.startsWith("image/") && !text) throw new Error("Ajoute une courte légende à l’image pour cette bêta.");
    if (visibility === "public" && !(await moderatePublicText(text, forceVideo || file?.type.startsWith("video/") ? "video" : "publication"))) return;
    const kind: "post" | "video" = forceVideo || file?.type.startsWith("video/") ? "video" : "post";
    const { data: post, error: postError } = await db.from("flamme_posts").insert({ author_id: me.id, group_id: groupId ?? null, content: text, visibility, kind }).select("id").single(); if (postError || !post?.id) throw postError ?? new Error("Publication impossible.");
    if (file) { const path = `${me.id}/${crypto.randomUUID()}.${safeExt(file)}`; const { error: uploadError } = await supabase.storage.from("flamme-media").upload(path, file, { cacheControl: "3600", upsert: false }); if (uploadError) { await db.from("flamme_posts").delete().eq("id", post.id); throw uploadError; } const mediaType = file.type.startsWith("video/") ? "video" : "image"; const { error: mediaError } = await db.from("flamme_post_media").insert({ post_id: post.id, path, media_type: mediaType }); if (mediaError) throw mediaError; }
    setContent(""); setFile(null); onCreated();
  } catch (cause) { setError(cause instanceof Error ? cause.message : "Publication impossible."); } finally { setBusy(false); } };
  return <Panel className="p-3.5 sm:p-4"><form onSubmit={submit}><div className="flex gap-3"><Avatar profile={me} /><textarea value={content} onChange={(e) => setContent(e.target.value)} maxLength={5000} rows={3} placeholder={forceVideo ? "Une légende pour cette vidéo…" : "Quoi de neuf ?"} className="min-h-20 min-w-0 flex-1 resize-none rounded-xl border-0 bg-[#F6F1E8]/65 px-3.5 py-3 text-sm outline-none ring-1 ring-transparent focus:ring-[#CE654B]/40" /></div>{file && <div className="mt-3 flex items-center justify-between rounded-xl bg-[#F6F1E8] px-3 py-2 text-xs"><span className="truncate">{file.name}</span><button type="button" onClick={() => setFile(null)}><X className="h-4 w-4" /></button></div>}{error && <p className="mt-3 rounded-xl bg-amber-50 px-3 py-2 text-xs text-amber-900">{error}</p>}<div className="mt-3 flex flex-wrap items-center gap-2"><label className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-[#E6DED2] px-3 py-2 text-xs font-semibold hover:bg-[#F6F1E8]"><ImageIcon className="h-4 w-4" /> Média<input type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" className="hidden" onChange={(e) => setFile(e.target.files?.[0] ?? null)} /></label><select value={visibility} onChange={(e) => setVisibility(e.target.value as any)} className="rounded-full border border-[#E6DED2] bg-white px-3 py-2 text-xs font-semibold"><option value="public">Public</option><option value="contacts">Contacts</option><option value="only_me">Moi uniquement</option></select><button disabled={busy || (!content.trim() && !file)} className="ml-auto rounded-full bg-[#CE654B] px-4 py-2 text-xs font-bold text-white disabled:opacity-40">{busy ? "Publication…" : "Publier"}</button></div></form></Panel>;
}

function FeedView({ me, kind, groupId, authorId, savedOnly = false, showComposer = false }: { me: Profile; kind?: "video"; groupId?: string; authorId?: string; savedOnly?: boolean; showComposer?: boolean }) {
  const [data, setData] = useState<FeedData>({ posts: [], profiles: new Map(), media: [], reactions: [], comments: [], saved: new Set() }); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { setLoading(true); setError(null); try {
    let savedIds: string[] | null = null; if (savedOnly) { const { data: savedRows, error: savedError } = await db.from("flamme_saved_items").select("post_id").eq("user_id", me.id).order("created_at", { ascending: false }); if (savedError) throw savedError; savedIds = (savedRows ?? []).map((row: any) => row.post_id); if (!savedIds.length) { setData({ posts: [], profiles: new Map(), media: [], reactions: [], comments: [], saved: new Set() }); setLoading(false); return; } }
    let query = db.from("flamme_posts").select("*").order("created_at", { ascending: false }).limit(50); if (kind) query = query.eq("kind", kind); if (groupId) query = query.eq("group_id", groupId); if (authorId) query = query.eq("author_id", authorId); if (savedIds) query = query.in("id", savedIds);
    const { data: posts, error: postError } = await query; if (postError) throw postError; const list = (posts ?? []) as Post[]; const ids = list.map((post) => post.id); if (!ids.length) { setData({ posts: [], profiles: new Map(), media: [], reactions: [], comments: [], saved: new Set() }); setLoading(false); return; }
    const [mediaRes, reactionRes, commentRes, savedRes] = await Promise.all([db.from("flamme_post_media").select("*").in("post_id", ids).order("position"), db.from("flamme_reactions").select("id,post_id,user_id").in("post_id", ids), db.from("flamme_comments").select("id,post_id,author_id,parent_id,content,created_at").in("post_id", ids).order("created_at"), db.from("flamme_saved_items").select("post_id").eq("user_id", me.id).in("post_id", ids)]);
    const comments = (commentRes.data ?? []) as Comment[]; const profileIds = Array.from(new Set([...list.map((post) => post.author_id), ...comments.map((comment) => comment.author_id)])); const { data: profiles } = await db.from("flamme_profiles").select("*").in("id", profileIds); setData({ posts: list, profiles: new Map((profiles ?? []).map((profile: Profile) => [profile.id, profile])), media: (mediaRes.data ?? []) as Media[], reactions: (reactionRes.data ?? []) as Reaction[], comments, saved: new Set((savedRes.data ?? []).map((row: any) => row.post_id as string)) });
  } catch (cause) { setError(cause instanceof Error ? cause.message : "Impossible de charger le fil."); } finally { setLoading(false); } }, [authorId, groupId, kind, me.id, savedOnly]);
  useEffect(() => { void load(); }, [load]);
  if (loading) return <div className="space-y-3">{showComposer && <Composer me={me} groupId={groupId} forceVideo={kind === "video"} onCreated={load} />}<Panel className="p-6 text-sm text-slate-500">Chargement du fil…</Panel></div>;
  return <div className="space-y-3">{showComposer && <Composer me={me} groupId={groupId} forceVideo={kind === "video"} onCreated={load} />}{error && <Panel className="border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</Panel>}{!data.posts.length ? <Empty icon={kind === "video" ? Video : Newspaper} title={savedOnly ? "Rien d’enregistré" : kind === "video" ? "Aucune vidéo" : "Le fil est calme"} text={savedOnly ? "Enregistre une publication ou une vidéo pour la retrouver ici." : "La première publication apparaîtra ici."} /> : data.posts.map((post) => <PostCard key={post.id} post={post} me={me} author={data.profiles.get(post.author_id)} media={data.media.filter((item) => item.post_id === post.id)} reactions={data.reactions.filter((item) => item.post_id === post.id)} comments={data.comments.filter((item) => item.post_id === post.id)} profiles={data.profiles} saved={data.saved.has(post.id)} onChanged={load} />)}</div>;
}

function PostCard({ post, me, author, media, reactions, comments, profiles, saved, onChanged }: { post: Post; me: Profile; author?: Profile; media: Media[]; reactions: Reaction[]; comments: Comment[]; profiles: Map<string, Profile>; saved: boolean; onChanged: () => void }) {
  const [comment, setComment] = useState(""); const [commentOpen, setCommentOpen] = useState(false); const liked = reactions.some((row) => row.user_id === me.id);
  const toggleLike = async () => { if (liked) await db.from("flamme_reactions").delete().eq("post_id", post.id).eq("user_id", me.id); else { await db.from("flamme_reactions").insert({ post_id: post.id, user_id: me.id }); await notify(post.author_id, me.id, "reaction", "post", post.id); } onChanged(); };
  const toggleSave = async () => { if (saved) await db.from("flamme_saved_items").delete().eq("post_id", post.id).eq("user_id", me.id); else await db.from("flamme_saved_items").insert({ post_id: post.id, user_id: me.id }); onChanged(); };
  const addComment = async (event: React.FormEvent) => { event.preventDefault(); const text = comment.trim(); if (!text) return; if (post.visibility === "public" && !(await moderatePublicText(text, "commentaire"))) return; const { error } = await db.from("flamme_comments").insert({ post_id: post.id, author_id: me.id, content: text }); if (!error) { setComment(""); await notify(post.author_id, me.id, "comment", "post", post.id); onChanged(); } };
  const share = async () => { const url = `${window.location.origin}/flamme/social`; try { if (navigator.share) await navigator.share({ title: "Flamme", text: post.content.slice(0, 120), url }); else { await navigator.clipboard.writeText(url); window.alert("Lien copié."); } } catch { /* cancelled */ } };
  const edit = async () => { const next = window.prompt("Modifier la publication", post.content); if (next === null || !next.trim()) return; await db.from("flamme_posts").update({ content: next.trim() }).eq("id", post.id); onChanged(); };
  const remove = async () => { if (!window.confirm("Supprimer cette publication ?")) return; await db.from("flamme_posts").delete().eq("id", post.id); onChanged(); };
  const report = async () => { const details = window.prompt("Pourquoi signales-tu ce contenu ?", ""); if (details === null) return; await db.from("flamme_reports").insert({ reporter_id: me.id, target_type: "post", target_id: post.id, reason: "other", details: details.slice(0, 1000) }); window.alert("Signalement envoyé."); };
  return <Panel className="overflow-hidden"><div className="flex items-start gap-3 p-4"><Avatar profile={author} /><div className="min-w-0 flex-1"><div className="flex items-start gap-2"><div className="min-w-0"><strong className="block truncate text-sm">{author?.display_name ?? "Utilisateur Flamme"}</strong><p className="truncate text-xs text-slate-500">{author ? `@${author.handle} · ` : ""}{dateLabel(post.created_at)} · {post.visibility === "public" ? "Public" : post.visibility === "contacts" ? "Contacts" : "Moi"}</p></div>{post.author_id === me.id ? <div className="ml-auto flex"><button onClick={() => void edit()} className="rounded-full p-2 text-slate-400 hover:bg-[#F6F1E8]" aria-label="Modifier"><Pencil className="h-4 w-4" /></button><button onClick={() => void remove()} className="rounded-full p-2 text-slate-400 hover:bg-red-50 hover:text-red-600" aria-label="Supprimer"><Trash2 className="h-4 w-4" /></button></div> : <button onClick={() => void report()} className="ml-auto rounded-full p-2 text-slate-400 hover:bg-[#F6F1E8]" aria-label="Signaler"><MoreHorizontal className="h-4 w-4" /></button>}</div>{post.content && <p className="mt-3 whitespace-pre-wrap break-words text-[15px] leading-relaxed text-slate-800">{post.content}</p>}</div></div>{media.map((item) => item.media_type === "video" ? <video key={item.id} src={mediaUrl(item.path)} controls muted playsInline preload="metadata" className="max-h-[72vh] w-full bg-black object-contain" /> : <img key={item.id} src={mediaUrl(item.path)} alt="" className="max-h-[72vh] w-full object-cover" />)}<div className="flex items-center gap-1 border-t border-[#E6DED2] px-2 py-1.5 text-xs"><button onClick={() => void toggleLike()} className={cx("flex flex-1 items-center justify-center gap-1.5 rounded-lg px-2 py-2 font-semibold hover:bg-[#F6F1E8]", liked && "text-[#CE654B]")}><Heart className={cx("h-4 w-4", liked && "fill-current")} /> {reactions.length || "J’aime"}</button><button onClick={() => setCommentOpen((v) => !v)} className="flex flex-1 items-center justify-center gap-1.5 rounded-lg px-2 py-2 font-semibold hover:bg-[#F6F1E8]"><MessageSquare className="h-4 w-4" /> {comments.length || "Commenter"}</button><button onClick={() => void share()} className="flex flex-1 items-center justify-center gap-1.5 rounded-lg px-2 py-2 font-semibold hover:bg-[#F6F1E8]"><Share2 className="h-4 w-4" /> Partager</button><button onClick={() => void toggleSave()} className={cx("rounded-lg p-2 hover:bg-[#F6F1E8]", saved && "text-[#CE654B]")} aria-label="Enregistrer"><Bookmark className={cx("h-4 w-4", saved && "fill-current")} /></button></div>{(commentOpen || comments.length > 0) && <div className="border-t border-[#E6DED2] bg-[#F6F1E8]/35 p-3"><div className="space-y-2">{comments.slice(-8).map((row) => { const person = profiles.get(row.author_id); return <div key={row.id} className="flex gap-2"><Avatar profile={person} size="sm" /><div className="rounded-2xl bg-white px-3 py-2 text-sm"><strong className="text-xs">{person?.display_name ?? "Utilisateur"}</strong><p className="mt-0.5 whitespace-pre-wrap text-slate-700">{row.content}</p></div></div>; })}</div><form onSubmit={addComment} className="mt-3 flex gap-2"><input value={comment} onChange={(e) => setComment(e.target.value)} maxLength={1500} placeholder="Écrire un commentaire…" className="min-w-0 flex-1 rounded-full border border-[#E6DED2] bg-white px-3.5 py-2 text-sm outline-none focus:border-[#CE654B]" /><button disabled={!comment.trim()} className="rounded-full bg-[#172638] px-3 text-xs font-bold text-white disabled:opacity-40">Envoyer</button></form></div>}</Panel>;
}

function GroupsView({ me }: { me: Profile }) {
  const [groups, setGroups] = useState<Group[]>([]); const [memberships, setMemberships] = useState<any[]>([]); const [selected, setSelected] = useState<Group | null>(null); const [creating, setCreating] = useState(false); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [visibility, setVisibility] = useState<Group["visibility"]>("public");
  const load = useCallback(async () => { const [{ data: groupRows }, { data: memberRows }] = await Promise.all([db.from("flamme_groups").select("*").order("created_at", { ascending: false }).limit(100), db.from("flamme_group_members").select("*").eq("user_id", me.id)]); setGroups(groupRows ?? []); setMemberships(memberRows ?? []); }, [me.id]); useEffect(() => { void load(); }, [load]);
  const membership = selected ? memberships.find((m) => m.group_id === selected.id) : null;
  const create = async (event: React.FormEvent) => { event.preventDefault(); const { data, error } = await db.from("flamme_groups").insert({ owner_id: me.id, name: name.trim(), description: description.trim(), visibility }).select("*").single(); if (!error && data) { setCreating(false); setName(""); setDescription(""); setSelected(data); await load(); } };
  const join = async () => { if (!selected) return; if (selected.visibility === "invite") return; await db.from("flamme_group_members").upsert({ group_id: selected.id, user_id: me.id, role: "member", status: selected.visibility === "public" ? "active" : "requested" }, { onConflict: "group_id,user_id" }); await load(); };
  if (selected) return <div className="space-y-3"><Panel className="p-5"><button onClick={() => setSelected(null)} className="text-xs font-semibold text-slate-500">← Tous les groupes</button><div className="mt-3 flex items-start gap-4"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[#172638] text-white"><UsersRound className="h-7 w-7" /></div><div className="min-w-0 flex-1"><h2 className="text-2xl font-extrabold">{selected.name}</h2><p className="mt-1 text-sm text-slate-600">{selected.description || "Aucune description."}</p><p className="mt-2 text-xs font-semibold text-slate-500">{selected.visibility === "public" ? "Groupe public" : selected.visibility === "private" ? "Groupe privé" : "Sur invitation"}</p></div>{!membership && selected.visibility !== "invite" && <button onClick={() => void join()} className="rounded-full bg-[#CE654B] px-4 py-2 text-xs font-bold text-white">{selected.visibility === "public" ? "Rejoindre" : "Demander"}</button>}{membership?.status === "requested" && <span className="rounded-full bg-amber-100 px-3 py-2 text-xs font-semibold text-amber-800">Demande envoyée</span>}</div></Panel>{(membership?.status === "active" || selected.visibility === "public") ? <FeedView me={me} groupId={selected.id} showComposer={membership?.status === "active"} /> : <Empty icon={LockKeyhole} title="Contenu privé" text="Les publications de ce groupe sont réservées à ses membres." />}</div>;
  return <div className="space-y-3"><Panel className="p-4"><div className="flex items-center justify-between"><div><h1 className="text-xl font-extrabold">Groupes</h1><p className="text-sm text-slate-500">Communautés publiques, privées ou sur invitation.</p></div><button onClick={() => setCreating((v) => !v)} className="flex items-center gap-1.5 rounded-full bg-[#172638] px-3.5 py-2 text-xs font-bold text-white"><Plus className="h-4 w-4" /> Créer</button></div>{creating && <form onSubmit={create} className="mt-4 grid gap-3 rounded-xl bg-[#F6F1E8]/65 p-3"><input required value={name} onChange={(e) => setName(e.target.value)} placeholder="Nom du groupe" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Description" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><select value={visibility} onChange={(e) => setVisibility(e.target.value as Group["visibility"])} className="rounded-xl border border-[#E6DED2] bg-white px-3 py-2.5 text-sm"><option value="public">Public</option><option value="private">Privé</option><option value="invite">Sur invitation</option></select><button className="rounded-xl bg-[#CE654B] px-4 py-2.5 text-sm font-bold text-white">Créer le groupe</button></form>}</Panel><div className="grid gap-3 sm:grid-cols-2">{groups.map((group) => <button key={group.id} onClick={() => setSelected(group)} className="rounded-[1.4rem] border border-[#E6DED2] bg-[#FFFDF9] p-4 text-left shadow-sm transition hover:-translate-y-0.5"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#172638] text-white"><UsersRound className="h-5 w-5" /></div><strong className="mt-3 block text-base">{group.name}</strong><p className="mt-1 line-clamp-2 text-xs leading-relaxed text-slate-500">{group.description || "Groupe Flamme"}</p><span className="mt-3 inline-block text-[10px] font-bold uppercase tracking-wider text-[#A84D38]">{group.visibility === "public" ? "Public" : group.visibility === "private" ? "Privé" : "Invitation"}</span></button>)}</div>{!groups.length && <Empty icon={UsersRound} title="Aucun groupe" text="Crée le premier groupe Flamme." />}</div>;
}

function PeopleView({ me, mode }: { me: Profile; mode: "discover" | "contacts" }) {
  const [profiles, setProfiles] = useState<Profile[]>([]); const [follows, setFollows] = useState<Follow[]>([]); const [query, setQuery] = useState("");
  const load = useCallback(async () => { const [{ data: profileRows }, { data: followRows }] = await Promise.all([db.from("flamme_profiles").select("*").neq("id", me.id).order("created_at", { ascending: false }).limit(100), db.from("flamme_follows").select("*").or(`follower_id.eq.${me.id},following_id.eq.${me.id}`)]); setProfiles(profileRows ?? []); setFollows(followRows ?? []); }, [me.id]); useEffect(() => { void load(); }, [load]);
  const outgoing = (id: string) => follows.find((f) => f.follower_id === me.id && f.following_id === id); const incoming = (id: string) => follows.find((f) => f.following_id === me.id && f.follower_id === id);
  const follow = async (person: Profile) => { const existing = outgoing(person.id); if (existing) await db.from("flamme_follows").delete().eq("id", existing.id); else { const status = person.is_private ? "pending" : "accepted"; await db.from("flamme_follows").insert({ follower_id: me.id, following_id: person.id, status }); await notify(person.id, me.id, status === "pending" ? "follow_request" : "follow", "profile", me.id); } await load(); };
  const accept = async (row: Follow) => { await db.from("flamme_follows").update({ status: "accepted" }).eq("id", row.id); await load(); };
  const visible = profiles.filter((person) => { const text = `${person.display_name} ${person.handle}`.toLowerCase(); if (query && !text.includes(query.toLowerCase())) return false; if (mode === "contacts") return !!outgoing(person.id) || !!incoming(person.id); return true; });
  return <div className="space-y-3"><Panel className="p-4"><h1 className="text-xl font-extrabold">{mode === "discover" ? "Découvrir" : "Contacts"}</h1><p className="mt-1 text-sm text-slate-500">{mode === "discover" ? "Trouve de nouvelles personnes sur Flamme." : "Abonnements, abonnés et demandes."}</p><label className="mt-4 flex items-center gap-2 rounded-xl border border-[#E6DED2] px-3 py-2.5"><Search className="h-4 w-4 text-slate-400" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Rechercher une personne" className="min-w-0 flex-1 bg-transparent text-sm outline-none" /></label></Panel><div className="space-y-2">{visible.map((person) => { const out = outgoing(person.id); const inc = incoming(person.id); return <Panel key={person.id} className="flex items-center gap-3 p-3"><Avatar profile={person} /><div className="min-w-0 flex-1"><strong className="block truncate text-sm">{person.display_name}</strong><span className="block truncate text-xs text-slate-500">@{person.handle}{person.is_private ? " · privé" : ""}</span></div>{inc?.status === "pending" && <button onClick={() => void accept(inc)} className="rounded-full bg-[#172638] px-3 py-2 text-xs font-bold text-white">Accepter</button>}<button onClick={() => void follow(person)} className={cx("rounded-full px-3 py-2 text-xs font-bold", out ? "border border-[#E6DED2] bg-white" : "bg-[#CE654B] text-white")}>{out ? out.status === "pending" ? "Demandé" : "Suivi" : "Suivre"}</button></Panel>; })}{!visible.length && <Empty icon={ContactRound} title="Personne ici" text="Essaie une autre recherche ou reviens plus tard." />}</div></div>;
}

function AlertsView({ me, onRead }: { me: Profile; onRead: () => void }) {
  const [items, setItems] = useState<any[]>([]); const [actors, setActors] = useState<Map<string, Profile>>(new Map());
  const load = useCallback(async () => { const { data } = await db.from("flamme_notifications").select("*").eq("user_id", me.id).order("created_at", { ascending: false }).limit(100); const rows = data ?? []; setItems(rows); const ids = Array.from(new Set(rows.map((row: any) => row.actor_id).filter(Boolean))) as string[]; if (ids.length) { const { data: profiles } = await db.from("flamme_profiles").select("*").in("id", ids); setActors(new Map((profiles ?? []).map((profile: Profile) => [profile.id, profile]))); } }, [me.id]); useEffect(() => { void load(); }, [load]);
  const markAll = async () => { await db.from("flamme_notifications").update({ read_at: new Date().toISOString() }).eq("user_id", me.id).is("read_at", null); await load(); onRead(); };
  const label = (item: any) => item.kind === "reaction" ? "a aimé ta publication" : item.kind === "comment" ? "a commenté ta publication" : item.kind === "follow_request" ? "souhaite te suivre" : item.kind === "follow" ? "te suit" : item.kind === "message" ? "t’a envoyé un message" : item.kind === "group_invite" ? "t’a invité dans un groupe" : "nouvelle activité";
  return <div className="space-y-3"><Panel className="flex items-center justify-between p-4"><div><h1 className="text-xl font-extrabold">Alertes</h1><p className="text-sm text-slate-500">Ton activité récente sur Flamme.</p></div><button onClick={() => void markAll()} className="text-xs font-bold text-[#A84D38]">Tout lire</button></Panel>{items.map((item) => { const actor = actors.get(item.actor_id); return <Panel key={item.id} className={cx("flex items-center gap-3 p-3", !item.read_at && "border-[#CE654B]/40 bg-[#CE654B]/[.035]")}><Avatar profile={actor} /><p className="min-w-0 flex-1 text-sm"><strong>{actor?.display_name ?? "Flamme"}</strong> {label(item)}.<span className="mt-0.5 block text-xs text-slate-400">{dateLabel(item.created_at)}</span></p>{!item.read_at && <span className="h-2.5 w-2.5 rounded-full bg-[#CE654B]" />}</Panel>; })}{!items.length && <Empty icon={Bell} title="Aucune alerte" text="Les réactions, commentaires et demandes apparaîtront ici." />}</div>;
}

function EventsView({ me }: { me: Profile }) {
  const [events, setEvents] = useState<EventRow[]>([]); const [attending, setAttending] = useState<Record<string, string>>({}); const [open, setOpen] = useState(false); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [date, setDate] = useState(""); const [place, setPlace] = useState("");
  const load = useCallback(async () => { const [{ data: rows }, { data: attendance }] = await Promise.all([db.from("flamme_events").select("*").order("starts_at", { ascending: true }).limit(100), db.from("flamme_event_attendees").select("event_id,status").eq("user_id", me.id)]); setEvents(rows ?? []); setAttending(Object.fromEntries((attendance ?? []).map((row: any) => [row.event_id, row.status]))); }, [me.id]); useEffect(() => { void load(); }, [load]);
  const create = async (e: React.FormEvent) => { e.preventDefault(); const { error } = await db.from("flamme_events").insert({ creator_id: me.id, title: title.trim(), description: description.trim(), starts_at: new Date(date).toISOString(), place: place.trim() || null, visibility: "public" }); if (!error) { setOpen(false); setTitle(""); setDescription(""); setDate(""); setPlace(""); await load(); } };
  const attend = async (eventId: string, status: string) => { await db.from("flamme_event_attendees").upsert({ event_id: eventId, user_id: me.id, status }, { onConflict: "event_id,user_id" }); await load(); };
  return <div className="space-y-3"><Panel className="p-4"><div className="flex items-center justify-between"><div><h1 className="text-xl font-extrabold">Événements</h1><p className="text-sm text-slate-500">Créer, inviter, participer.</p></div><button onClick={() => setOpen((v) => !v)} className="rounded-full bg-[#172638] px-3.5 py-2 text-xs font-bold text-white">+ Créer</button></div>{open && <form onSubmit={create} className="mt-4 grid gap-2 rounded-xl bg-[#F6F1E8]/65 p-3"><input required value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Titre" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Description" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><input required type="datetime-local" value={date} onChange={(e) => setDate(e.target.value)} className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><input value={place} onChange={(e) => setPlace(e.target.value)} placeholder="Lieu (facultatif)" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><button className="rounded-xl bg-[#CE654B] px-4 py-2.5 text-sm font-bold text-white">Publier l’événement</button></form>}</Panel>{events.map((event) => <Panel key={event.id} className="p-4"><div className="flex gap-3"><div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-[#CE654B]/10 text-[#A84D38]"><CalendarDays className="h-5 w-5" /></div><div className="min-w-0 flex-1"><strong className="block text-base">{event.title}</strong><p className="mt-1 text-sm text-slate-600">{new Date(event.starts_at).toLocaleString("fr-FR", { dateStyle: "medium", timeStyle: "short" })}{event.place ? ` · ${event.place}` : ""}</p>{event.description && <p className="mt-2 text-sm leading-relaxed text-slate-600">{event.description}</p>}<div className="mt-3 flex flex-wrap gap-2">{[["going","J’y vais"],["maybe","Peut-être"],["declined","Non"]].map(([status,label]) => <button key={status} onClick={() => void attend(event.id, status)} className={cx("rounded-full border px-3 py-1.5 text-xs font-semibold", attending[event.id] === status ? "border-[#CE654B] bg-[#CE654B] text-white" : "border-[#E6DED2] bg-white")}>{label}</button>)}</div></div></div></Panel>)}{!events.length && <Empty icon={CalendarDays} title="Aucun événement" text="Crée un événement public pour commencer." />}</div>;
}

function SearchView({ me }: { me: Profile }) {
  const [query, setQuery] = useState(""); const [profiles, setProfiles] = useState<Profile[]>([]); const [groups, setGroups] = useState<Group[]>([]); const [posts, setPosts] = useState<Post[]>([]); const [busy, setBusy] = useState(false);
  const search = async (e: React.FormEvent) => { e.preventDefault(); const q = query.trim().replace(/[%_]/g, ""); if (q.length < 2) return; setBusy(true); const [p, g, po] = await Promise.all([db.from("flamme_profiles").select("*").neq("id", me.id).or(`handle.ilike.%${q}%,display_name.ilike.%${q}%`).limit(12), db.from("flamme_groups").select("*").or(`name.ilike.%${q}%,description.ilike.%${q}%`).limit(12), db.from("flamme_posts").select("*").eq("visibility", "public").ilike("content", `%${q}%`).limit(15)]); setProfiles(p.data ?? []); setGroups(g.data ?? []); setPosts(po.data ?? []); setBusy(false); };
  return <div className="space-y-3"><Panel className="p-4"><h1 className="text-xl font-extrabold">Recherche</h1><form onSubmit={search} className="mt-3 flex gap-2"><input autoFocus value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Personnes, groupes, publications…" className="min-w-0 flex-1 rounded-xl border border-[#E6DED2] px-3.5 py-3 text-sm outline-none focus:border-[#CE654B]" /><button className="rounded-xl bg-[#172638] px-4 text-sm font-bold text-white">{busy ? "…" : "Chercher"}</button></form></Panel>{profiles.length > 0 && <Panel className="p-4"><strong>Personnes</strong><div className="mt-3 grid gap-2 sm:grid-cols-2">{profiles.map((p) => <div key={p.id} className="flex items-center gap-2 rounded-xl bg-[#F6F1E8]/60 p-2.5"><Avatar profile={p} size="sm" /><span className="min-w-0"><strong className="block truncate text-sm">{p.display_name}</strong><span className="block truncate text-xs text-slate-500">@{p.handle}</span></span></div>)}</div></Panel>}{groups.length > 0 && <Panel className="p-4"><strong>Groupes</strong><div className="mt-2 space-y-2">{groups.map((g) => <div key={g.id} className="rounded-xl bg-[#F6F1E8]/60 p-3"><strong className="text-sm">{g.name}</strong><p className="mt-1 line-clamp-2 text-xs text-slate-500">{g.description}</p></div>)}</div></Panel>}{posts.length > 0 && <Panel className="p-4"><strong>Publications</strong><div className="mt-2 space-y-2">{posts.map((p) => <div key={p.id} className="rounded-xl bg-[#F6F1E8]/60 p-3 text-sm text-slate-700">{p.content}</div>)}</div></Panel>}{!busy && query && !profiles.length && !groups.length && !posts.length && <Empty icon={Search} title="Aucun résultat" text="Essaie avec d’autres mots." />}</div>;
}

function AccountView({ me, onChange }: { me: Profile; onChange: (p: Profile) => void }) {
  const [editing, setEditing] = useState(false); const [name, setName] = useState(me.display_name); const [bio, setBio] = useState(me.bio || ""); const [city, setCity] = useState(me.city || ""); const [website, setWebsite] = useState(me.website || "");
  const save = async (e: React.FormEvent) => { e.preventDefault(); const { data, error } = await db.from("flamme_profiles").update({ display_name: name.trim(), bio: bio.trim(), city: city.trim() || null, website: website.trim() || null }).eq("id", me.id).select("*").single(); if (!error && data) { onChange(data); setEditing(false); } };
  const uploadAvatar = async (file?: File) => { if (!file || !file.type.match(/^image\/(jpeg|png|webp)$/) || file.size > 5 * 1024 * 1024) return; const path = `${me.id}/avatar-${Date.now()}.${safeExt(file)}`; const { error } = await supabase.storage.from("flamme-avatars").upload(path, file); if (error) return; const { data } = await db.from("flamme_profiles").update({ avatar_path: path }).eq("id", me.id).select("*").single(); if (data) onChange(data); };
  return <div className="space-y-3"><Panel className="overflow-hidden"><div className="h-36 bg-gradient-to-br from-[#172638] via-[#263d56] to-[#CE654B]" /><div className="px-5 pb-5"><div className="-mt-10 flex items-end justify-between"><label className="relative cursor-pointer rounded-full bg-white p-1 shadow"><Avatar profile={me} size="lg" /><input type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={(e) => void uploadAvatar(e.target.files?.[0])} /></label><button onClick={() => setEditing((v) => !v)} className="rounded-full border border-[#E6DED2] bg-white px-4 py-2 text-xs font-bold">Modifier</button></div><h1 className="mt-3 text-2xl font-extrabold">{me.display_name}</h1><p className="text-sm text-slate-500">@{me.handle}</p>{me.bio && <p className="mt-3 whitespace-pre-wrap text-sm leading-relaxed text-slate-700">{me.bio}</p>}<p className="mt-3 text-xs text-slate-500">{[me.city, me.website].filter(Boolean).join(" · ")}</p>{editing && <form onSubmit={save} className="mt-4 grid gap-2 rounded-xl bg-[#F6F1E8]/70 p-3"><input value={name} onChange={(e) => setName(e.target.value)} className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><textarea value={bio} onChange={(e) => setBio(e.target.value)} maxLength={500} placeholder="Biographie" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><input value={city} onChange={(e) => setCity(e.target.value)} placeholder="Ville" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><input value={website} onChange={(e) => setWebsite(e.target.value)} placeholder="Lien" className="rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><button className="rounded-xl bg-[#CE654B] px-4 py-2.5 text-sm font-bold text-white">Enregistrer</button></form>}</div></Panel><h2 className="px-1 text-sm font-bold text-slate-500">Mes publications</h2><FeedView me={me} authorId={me.id} showComposer={false} /></div>;
}

function SettingsView({ me, onChange }: { me: Profile; onChange: (p: Profile) => void }) {
  const [handle, setHandle] = useState(""); const [blocked, setBlocked] = useState<Profile[]>([]); const [message, setMessage] = useState<string | null>(null);
  const loadBlocked = useCallback(async () => { const { data: blocks } = await db.from("flamme_blocks").select("blocked_id").eq("blocker_id", me.id); const ids = (blocks ?? []).map((b: any) => b.blocked_id); if (!ids.length) { setBlocked([]); return; } const { data } = await db.from("flamme_profiles").select("*").in("id", ids); setBlocked(data ?? []); }, [me.id]); useEffect(() => { void loadBlocked(); }, [loadBlocked]);
  const update = async (patch: Partial<Profile>) => { const { data, error } = await db.from("flamme_profiles").update(patch).eq("id", me.id).select("*").single(); if (!error && data) onChange(data); };
  const block = async (e: React.FormEvent) => { e.preventDefault(); const value = handle.trim().replace(/^@/, ""); const { data: person } = await db.from("flamme_profiles").select("id").eq("handle", value).maybeSingle(); if (!person?.id) { setMessage("Compte introuvable."); return; } const { error } = await db.from("flamme_blocks").insert({ blocker_id: me.id, blocked_id: person.id }); setMessage(error ? "Impossible de bloquer ce compte." : "Compte bloqué."); setHandle(""); await loadBlocked(); };
  const removeProfile = async () => { if (!window.confirm("Supprimer ton profil Flamme et ses données sociales ? Cette action ne supprime pas ton compte du site, mais elle efface tes données Flamme.")) return; await db.from("flamme_profiles").delete().eq("id", me.id); window.location.reload(); };
  return <div className="space-y-3"><Panel className="p-5"><h1 className="text-xl font-extrabold">Paramètres</h1><p className="mt-1 text-sm text-slate-500">Confidentialité, sécurité et gestion du profil Flamme.</p></Panel><Panel className="p-5"><h2 className="font-bold">Confidentialité</h2><label className="mt-4 flex items-center justify-between gap-3"><span><strong className="block text-sm">Profil privé</strong><span className="text-xs text-slate-500">Les nouveaux abonnements nécessitent ton accord.</span></span><input type="checkbox" checked={me.is_private} onChange={(e) => void update({ is_private: e.target.checked })} className="h-5 w-5 accent-[#CE654B]" /></label><label className="mt-4 block text-sm font-semibold">Qui peut m’écrire ?<select value={me.allow_messages} onChange={(e) => void update({ allow_messages: e.target.value as Profile["allow_messages"] })} className="mt-2 w-full rounded-xl border border-[#E6DED2] bg-white px-3 py-2.5"><option value="everyone">Tout le monde</option><option value="contacts">Mes contacts</option><option value="nobody">Personne</option></select></label></Panel><Panel className="p-5"><h2 className="font-bold">Comptes bloqués</h2><form onSubmit={block} className="mt-3 flex gap-2"><input value={handle} onChange={(e) => setHandle(e.target.value)} placeholder="@identifiant" className="min-w-0 flex-1 rounded-xl border border-[#E6DED2] px-3 py-2.5 text-sm" /><button className="rounded-xl bg-[#172638] px-4 text-xs font-bold text-white">Bloquer</button></form>{message && <p className="mt-2 text-xs text-slate-500">{message}</p>}<div className="mt-3 space-y-2">{blocked.map((person) => <div key={person.id} className="flex items-center gap-2 rounded-xl bg-[#F6F1E8]/60 p-2"><Avatar profile={person} size="sm" /><span className="text-sm font-semibold">@{person.handle}</span><button onClick={async () => { await db.from("flamme_blocks").delete().eq("blocker_id", me.id).eq("blocked_id", person.id); await loadBlocked(); }} className="ml-auto text-xs font-bold text-[#A84D38]">Débloquer</button></div>)}</div></Panel><Panel className="p-5"><div className="flex items-start gap-3"><LockKeyhole className="mt-0.5 h-5 w-5 text-[#CE654B]" /><div><h2 className="font-bold">Messages chiffrés</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">La clé privée de messagerie reste dans le navigateur via IndexedDB. Un changement d’appareil peut rendre l’ancien historique illisible si aucune clé n’a été enveloppée pour ce nouvel appareil. C’est volontairement explicite en bêta.</p></div></div></Panel><Panel className="p-5"><button onClick={() => void supabase.auth.signOut()} className="flex items-center gap-2 text-sm font-bold text-slate-700"><LogOut className="h-4 w-4" /> Se déconnecter</button><button onClick={() => void removeProfile()} className="mt-5 flex items-center gap-2 text-sm font-bold text-red-600"><Trash2 className="h-4 w-4" /> Supprimer mon profil Flamme</button></Panel></div>;
}
